        "text": "وجہ تسمیہ اور تعارف:\nیہ سورت مبارکہ خیبر پختونخوا ٹیکسٹ بک بورڈ کے مطالعہ قرآن حکیم نصاب برائے جماعت ہشتم میں شامل ہے۔\n\nمرکزی مضامین:\nشاہی خواب کی تعبیر، مصر کا اقتدار، بھائیوں کی آمد، حضرت یعقوبؑ سے ملاپ اور شکر گزاری\n\nاس سورت کا بنیادی مقصد عقائدِ اسلامیہ (توحید، رسالت، آخرت) کا اثبات، دلوں میں خوفِ خدا پیدا کرنا، اور انسان کو نیک اعمال اور صبر و استقامت کی ترغیب دینا ہے۔",
